package webui

const awsPageTemplate = `
{{define "aws"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>AWS EC2 · Aiori Compute</title>{{template "styles" .}}
<style>
.aws-metrics-panel{margin:18px 0;padding:18px;border:1px solid var(--line,#e5e7eb);border-radius:14px;background:var(--surface,#fff)}.aws-metric-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.aws-metric-card{min-width:0;padding:14px;border:1px solid var(--line,#e5e7eb);border-radius:11px}.aws-metric-card>div{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px;color:var(--muted,#64748b)}.aws-metric-card strong{font-size:20px;color:var(--text,#111827);font-variant-numeric:tabular-nums}.aws-metric-card canvas{display:block;width:100%;height:105px;margin-top:10px}.aws-page{max-width:1440px;margin:0 auto;width:100%;min-width:0}.aws-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(280px,.9fr);gap:20px;align-items:start}.aws-card{min-width:0}.aws-inventory{margin-top:22px;min-width:0}.aws-table-scroll{width:100%;overflow-x:auto;overflow-y:visible;overscroll-behavior-x:contain;border:1px solid var(--line,#e5e7eb);border-radius:12px}.aws-table{width:100%;min-width:900px;border-collapse:separate;border-spacing:0}.aws-table th{position:sticky;top:0;z-index:2;background:var(--surface,#fff);text-align:left;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted,#64748b);padding:13px 15px;white-space:nowrap;border-bottom:1px solid var(--line,#e5e7eb)}.aws-table td{padding:13px 15px;border-bottom:1px solid var(--line,#e5e7eb);vertical-align:middle;font-size:13px;white-space:nowrap}.aws-table tr:last-child td{border-bottom:0}.aws-table tbody tr:hover{background:var(--surface-muted,#f8fafc)}.aws-id{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}.aws-name{font-weight:650}.aws-sub{display:block;color:var(--muted,#64748b);font-size:11px;margin-top:4px}.aws-state{display:inline-flex;align-items:center;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:700;background:#f1f5f9;color:#334155}.aws-state.running{background:#dcfce7;color:#166534}.aws-state.pending,.aws-state.stopping{background:#fef3c7;color:#92400e}.aws-state.stopped{background:#e2e8f0;color:#475569}.aws-row-actions{display:flex;gap:7px;align-items:center}.aws-row-actions form{margin:0}.aws-btn{font:inherit;font-size:12px;padding:7px 10px;border:1px solid var(--line,#dbe2ea);border-radius:8px;background:var(--surface,#fff);color:inherit;text-decoration:none;cursor:pointer}.aws-btn:hover{background:var(--surface-muted,#f8fafc)}.aws-btn-danger{color:#b91c1c;border-color:#fecaca}.aws-detail-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:16px 0}.aws-detail{min-width:0;padding:12px;border:1px solid var(--line,#e5e7eb);border-radius:10px}.aws-detail small{display:block;color:var(--muted,#64748b);font-size:11px;margin-bottom:6px}.aws-detail strong{overflow-wrap:anywhere;font-size:13px}.aws-empty{padding:32px 20px;text-align:center;color:var(--muted,#64748b)}.aws-toolbar{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:14px}.aws-toolbar p{margin:0}.aws-scroll-note{font-size:11px;color:var(--muted,#64748b);margin-top:8px}@media(max-width:950px){.aws-grid{grid-template-columns:1fr}.aws-detail-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.aws-metric-grid{grid-template-columns:1fr}.aws-detail-grid{grid-template-columns:1fr}.aws-toolbar{align-items:flex-start;flex-direction:column}}
</style></head><body class="app-body aws-inventory-body"><a class="skip-link" href="#main-content">Skip to main content</a><div class="app-shell aws-shell">{{template "sidebar" .}}<main class="main-area aws-main" id="main-content"><header class="topbar aws-topbar"><div class="breadcrumbs">Infrastructure / <strong>AWS EC2</strong></div><span class="env-pill">AWS RESOURCE INVENTORY</span></header><div class="content aws-content"><div class="aws-page">
<div class="aws-hero"><div><div class="eyebrow">Cloud infrastructure / AWS</div><h1>EC2 instances</h1><p>Provision and operate controller-managed compute hosts. Track AWS lifecycle state alongside worker-agent enrollment without confusing the two signals.</p><div class="aws-hero-meta"><span class="aws-region-chip"><i></i>{{.Region}}</span><span class="aws-meta-copy">Managed resources · AWS EC2</span><span class="aws-meta-copy">Live telemetry · Stored in this platform</span></div></div><div class="aws-hero-mark" aria-hidden="true"><span>EC2</span><small>COMPUTE FLEET</small></div></div>{{if not .HasInstance}}<div class="aws-overview" aria-label="EC2 inventory overview"><article class="aws-overview-card"><span class="aws-overview-icon">▦</span><div><small>Managed instances</small><strong>{{len .Instances}}</strong><span>In selected region</span></div></article><article class="aws-overview-card"><span class="aws-overview-icon">⌖</span><div><small>Selected region</small><strong class="aws-region-value">{{.Region}}</strong><span>Inventory scope</span></div></article><article class="aws-overview-card"><span class="aws-overview-icon">↗</span><div><small>Worker readiness</small><strong>Separate signal</strong><span>Verified by agent heartbeat</span></div></article></div>
{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}{{if .Error}}<div class="notice error" role="alert">{{.Error}}</div>{{end}}
<div class="aws-grid">
<section class="section-card aws-card"><div class="section-head"><div><span class="aws-section-index">01 / PROVISION</span><h2 class="section-title">Launch a node</h2><div class="section-subtitle">AWS credentials stay on the controller host</div></div></div><form method="post" action="/aws/instances" class="form-stack"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="client_token" value="{{.IdempotencyKey}}"><div class="field"><label for="ec2-name">Instance name</label><input id="ec2-name" name="name" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9 _.-]*" value="aiori-worker-test"></div><div class="field"><label for="ec2-region">AWS region</label><input id="ec2-region" name="region" required value="{{.Region}}" placeholder="ap-south-1"></div><div class="field"><label for="ec2-type">Instance type</label><select id="ec2-type" name="instance_type"><option value="t3.micro">t3.micro · connectivity test only</option><option value="t3.small">t3.small · connectivity test only</option><option value="c8i.xlarge">c8i.xlarge · KVM + nested virtualization</option></select></div><div class="field"><label for="ec2-ami">Ubuntu x86_64 AMI ID</label><input id="ec2-ami" name="image_id" required value="{{.DefaultAMI}}" placeholder="ami-0123456789abcdef0"></div><div class="field"><label for="ec2-subnet">Subnet ID (optional)</label><input id="ec2-subnet" name="subnet_id" value="{{.DefaultSubnet}}" placeholder="subnet-0123456789abcdef0"></div><div class="field"><label for="ec2-groups">Worker security group IDs (optional)</label><input id="ec2-groups" name="security_group_ids" value="{{.DefaultWorkerSecurityGroup}}" placeholder="sg-0123456789abcdef0"><small>Use a security group in the controller VPC. When bootstrap is enabled, the controller agent port is opened only from the controller security group.</small></div><div class="field"><label for="ec2-key">EC2 key pair name (optional)</label><input id="ec2-key" name="key_name" placeholder="admin-key"></div><div class="field"><label for="ec2-profile">Worker IAM instance profile (required)</label><input id="ec2-profile" name="instance_profile" value="{{.DefaultWorkerInstanceProfile}}" placeholder="aiori-worker-ssm" required></div><button class="btn btn-primary aws-launch-btn" type="submit" {{if not .BootstrapEnabled}}disabled title="Configure worker bootstrap before launching"{{end}}><span>{{if .BootstrapEnabled}}Launch bootstrapped worker{{else}}Bootstrap configuration required{{end}}</span><span aria-hidden="true">→</span></button></form></section>
<section class="section-card aws-card"><div class="section-head"><div><span class="aws-section-index">02 / READINESS</span><h2 class="section-title">Node readiness</h2><div class="section-subtitle">Cloud state and worker health are different signals</div></div></div>{{if .BootstrapEnabled}}<div class="callout">Worker bootstrap is configured. Launch user data installs checksum-verified agent, hypervisor, and image artifacts; retrieves the worker secret from SSM Parameter Store using the instance role; and starts the agent. The worker auto-enrolls on its first authenticated heartbeat. Agent health remains separate from EC2 state.</div><details style="margin-top:12px"><summary>Inspect generated EC2 user data (no secret value included)</summary><pre style="max-height:360px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;padding:12px;background:var(--surface-muted,#f8fafc);border-radius:8px">{{.UserData}}</pre></details>{{else}}<div class="callout">Worker bootstrap is not configured. Launching is disabled because an unbootstrapped EC2 machine cannot join this controller. Configure the required controller environment variables and worker IAM instance profile, then restart the controller. The server independently enforces this requirement.</div>{{end}}<p class="section-subtitle">The t3 sizes are connectivity-test machines only. Select c8i.xlarge for the compute-worker profile: the controller explicitly requests AWS nested virtualization at launch. This is a more expensive temporary host; check price, quota, and AZ capacity before launch. Still verify the agent's /dev/kvm and Cloud Hypervisor probe before scheduling workloads.</p><p class="section-subtitle">Use <a href="/workers">Worker inventory</a> to inspect registered agent heartbeats. This EC2 page reports AWS lifecycle state only.</p></section>
</div>
<section class="section-card aws-inventory"><div class="aws-toolbar"><div><span class="aws-section-index">03 / INVENTORY</span><h2 class="section-title">Managed EC2 inventory</h2><p class="section-subtitle">Only instances tagged ManagedBy=aiori-controller in the selected region are listed. Refresh inventory from AWS to load the latest cloud state.</p></div><div class="aws-inventory-controls"><label class="aws-search"><span class="sr-only">Search instances</span><input type="search" data-aws-search placeholder="Search name or instance ID…" autocomplete="off"></label><label class="aws-filter-label">State <select data-aws-state-filter><option value="all">All states</option><option value="running">Running</option><option value="pending">Pending</option><option value="stopped">Stopped</option><option value="stopping">Stopping</option></select></label></div><form method="get" action="/aws" class="field-actions"><label for="inventory-region">Region</label><input id="inventory-region" name="region" value="{{.Region}}" placeholder="ap-south-1" required style="max-width:170px"><button class="aws-btn aws-refresh-btn" type="submit"><span aria-hidden="true">↻</span> Refresh inventory</button></form></div>
{{if .InventoryError}}<div class="notice error" role="alert">{{.InventoryError}}</div>{{end}}
{{if .Instances}}<div class="aws-table-scroll" role="region" aria-label="Managed EC2 instances" tabindex="0"><table class="aws-table"><thead><tr><th>Name / instance ID</th><th>AWS state</th><th>Worker agent</th><th>Instance type</th><th>Public / private IP</th><th>Availability zone</th><th>Actions</th></tr></thead><tbody>{{range .Instances}}<tr data-aws-row data-aws-state="{{.Instance.State.Name}}"><td><span class="aws-name">{{if .Instance.Name}}{{.Instance.Name}}{{else}}Unnamed instance{{end}}</span><span class="aws-sub aws-id">{{.Instance.ID}}</span></td><td><span class="aws-state {{.Instance.State.Name}}">{{.Instance.State.Name}}</span></td><td>{{if .HasWorker}}<span class="aws-state {{.Worker.State}}">{{.Worker.State}}</span><span class="aws-sub">{{if .Worker.LastHeartbeat.IsZero}}No heartbeat{{else}}{{.Worker.LastHeartbeat.Format "15:04:05 UTC"}}{{end}}</span>{{else}}<span class="aws-state">Not enrolled</span><span class="aws-sub">No agent heartbeat</span>{{end}}</td><td>{{.Instance.Type}}</td><td>{{if .Instance.PublicIP}}{{.Instance.PublicIP}}{{else}}—{{end}}<span class="aws-sub">{{if .Instance.PrivateIP}}{{.Instance.PrivateIP}}{{else}}No private IP{{end}}</span></td><td>{{.Instance.Placement.AvailabilityZone}}</td><td><div class="aws-row-actions"><a class="aws-btn" href="/aws/instances/{{.Instance.ID}}?region={{$.Region}}">Inspect</a>{{if eq .Instance.State.Name "stopped"}}<form method="post" action="/aws/instances/{{.Instance.ID}}/start"><input type="hidden" name="csrf_token" value="{{$.CSRFToken}}"><input type="hidden" name="region" value="{{$.Region}}"><button class="aws-btn" type="submit">Start</button></form>{{else if eq .Instance.State.Name "running"}}<form method="post" action="/aws/instances/{{.Instance.ID}}/stop" data-aws-confirm="Stop this EC2 instance?"><input type="hidden" name="csrf_token" value="{{$.CSRFToken}}"><input type="hidden" name="region" value="{{$.Region}}"><button class="aws-btn" type="submit">Stop</button></form>{{end}}{{if and (ne .Instance.State.Name "terminated") (ne .Instance.State.Name "shutting-down")}}<form method="post" action="/aws/instances/{{.Instance.ID}}/terminate" data-aws-confirm="Terminate this EC2 instance permanently? This cannot be undone."><input type="hidden" name="csrf_token" value="{{$.CSRFToken}}"><input type="hidden" name="region" value="{{$.Region}}"><button class="aws-btn aws-btn-danger" type="submit">Terminate</button></form>{{end}}</div></td></tr>{{end}}</tbody></table></div><p class="aws-scroll-note"><span data-aws-visible-count>{{len .Instances}}</span> instances shown · Use the workspace scrollbar to browse the page; the table scrolls horizontally on smaller screens.</p><div class="aws-no-results" data-aws-no-results hidden>No instances match this search and state filter.</div>{{else if not .InventoryError}}<div class="aws-empty"><strong>No managed instances found in {{.Region}}.</strong><p>Launch an instance above. It will appear here after AWS accepts the request and the next inventory refresh completes.</p></div>{{end}}</section>
{{end}}{{if .HasInstance}}<section class="section-card aws-inventory"><div class="section-head"><div><a class="aws-btn" href="/aws?region={{.Region}}">← All EC2 instances</a><h2 class="section-title">Instance details</h2><div class="section-subtitle">{{.Instance.Name}} · {{.Instance.ID}}</div></div><span class="aws-state {{.Instance.State.Name}}">{{.Instance.State.Name}}</span></div><section class="aws-metrics-panel" data-ec2-metrics data-instance-id="{{.Instance.ID}}" data-region="{{.Region}}" aria-labelledby="ec2-metrics-title"><div class="aws-toolbar"><div><span class="aws-section-index">LIVE / TELEMETRY</span><h3 id="ec2-metrics-title" class="section-title">Instance monitoring</h3><p class="section-subtitle">Guest metrics reported directly to this platform every 60 seconds. Recent 24-hour history is retained by the controller.</p></div><span class="aws-state" data-metrics-status>Waiting for telemetry</span></div><div class="aws-metric-grid"><article class="aws-metric-card"><div><span>CPU utilization</span><strong data-metric-value="cpu">—</strong></div><canvas data-metric-chart="cpu" aria-label="CPU utilization chart"></canvas></article><article class="aws-metric-card"><div><span>Memory utilization</span><strong data-metric-value="memory">—</strong></div><canvas data-metric-chart="memory" aria-label="Memory utilization chart"></canvas></article><article class="aws-metric-card"><div><span>Root disk utilization</span><strong data-metric-value="disk">—</strong></div><canvas data-metric-chart="disk" aria-label="Disk utilization chart"></canvas></article><article class="aws-metric-card"><div><span>Network traffic</span><strong data-metric-value="network">—</strong></div><canvas data-metric-chart="network" aria-label="Network bytes chart"></canvas></article></div><p class="aws-scroll-note" data-metrics-updated>Metrics are collected by the instance agent; no CloudWatch dependency.</p></section>{{if .HasAgent}}<div class="callout">Worker agent: <strong>{{.Agent.State}}</strong> · Last heartbeat: {{if .Agent.LastHeartbeat.IsZero}}never{{else}}{{.Agent.LastHeartbeat.Format "2006-01-02 15:04:05 UTC"}}{{end}} · Endpoint: <code>{{.Agent.Endpoint}}</code>. A healthy agent state confirms the Cloud Hypervisor probe; EC2 state is independent.</div>{{else}}<div class="notice error">Worker agent: <strong>Not enrolled</strong>. No authenticated heartbeat has registered this EC2 instance as a node. Check the instance profile, cloud-init log, controller URL, and private security-group path.</div>{{end}}<div class="aws-detail-grid"><div class="aws-detail"><small>Instance type</small><strong>{{.Instance.Type}}</strong></div><div class="aws-detail"><small>AMI / architecture</small><strong>{{.Instance.ImageID}} / {{.Instance.Architecture}}</strong></div><div class="aws-detail"><small>Nested virtualization</small><strong>{{if .Instance.NestedVirtualization}}{{.Instance.NestedVirtualization}}{{else}}Not enabled / not reported{{end}}</strong></div><div class="aws-detail"><small>Launch time (UTC)</small><strong>{{.Instance.LaunchTime}}</strong></div><div class="aws-detail"><small>Public IP</small><strong>{{if .Instance.PublicIP}}{{.Instance.PublicIP}}{{else}}Not assigned{{end}}</strong></div><div class="aws-detail"><small>Private IP</small><strong>{{if .Instance.PrivateIP}}{{.Instance.PrivateIP}}{{else}}Not assigned{{end}}</strong></div><div class="aws-detail"><small>VPC / subnet</small><strong>{{.Instance.VPCID}} / {{.Instance.SubnetID}}</strong></div><div class="aws-detail"><small>Key pair</small><strong>{{if .Instance.KeyName}}{{.Instance.KeyName}}{{else}}None{{end}}</strong></div><div class="aws-detail"><small>Security groups</small><strong>{{range $i,$g := .Instance.SecurityGroups}}{{if $i}}, {{end}}{{$g}}{{else}}None returned{{end}}</strong></div><div class="aws-detail"><small>Availability zone</small><strong>{{.Instance.Placement.AvailabilityZone}}</strong></div></div>{{if .Instance.StateReason}}<div class="notice error">{{.Instance.StateReason}}</div>{{end}}{{if and .Instance.PublicIP .Instance.KeyName}}<div class="callout">SSH (Ubuntu AMI): <code>ssh -i /path/to/{{.Instance.KeyName}}.pem ubuntu@{{.Instance.PublicIP}}</code>. Replace the key path with your local private-key file; never upload the private key to the controller.</div>{{end}}<div class="field-actions"><a class="aws-btn" target="_blank" rel="noopener noreferrer" href="https://console.aws.amazon.com/ec2/home?region={{.Region}}#InstanceDetails:instanceId={{.Instance.ID}}">Connect in AWS console</a><a class="aws-btn" href="/aws/instances/{{.Instance.ID}}?region={{.Region}}">Refresh details</a>{{if eq .Instance.State.Name "stopped"}}<form method="post" action="/aws/instances/{{.Instance.ID}}/start"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="region" value="{{.Region}}"><button class="btn btn-primary" type="submit">Start instance</button></form>{{else if eq .Instance.State.Name "running"}}<form method="post" action="/aws/instances/{{.Instance.ID}}/stop" data-aws-confirm="Stop this EC2 instance?"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="region" value="{{.Region}}"><button class="btn btn-secondary" type="submit">Stop instance</button></form>{{end}}{{if and (ne .Instance.State.Name "terminated") (ne .Instance.State.Name "shutting-down")}}<form method="post" action="/aws/instances/{{.Instance.ID}}/terminate" data-aws-confirm="Terminate this EC2 instance permanently? This cannot be undone."><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="region" value="{{.Region}}"><button class="btn btn-secondary aws-btn-danger" type="submit">Terminate instance</button></form>{{end}}</div></section>{{end}}
</div></div></main></div><script src="/assets/ui.js" defer></script></body></html>{{end}}`
